	}

	@ConfigItem(
			keyName = "snowDensity",
			name = "Snow Density",
			description = "<html>Sets the number of Snow objects that spawn while Snowy<br>Max = 2000</html>",
			section = weatherToggles,
			position = 17
	)
	@Range(max = 2000)
	default int snowDensity()
