	}

	@ConfigItem(
			keyName = "enableClouds",
			name = "Clouds Enabled",
			description = "Allows Cloud objects to appear while Cloudy or Partly Cloudy",
			section = weatherToggles,
			position = 18
	)
	default boolean enableClouds()
