	}

	@ConfigItem(
			keyName = "cloudyDensity",
			name = "Cloud Density",
			description = "<html>Sets the number of Cloud objects that spawn while Cloudy<br>Max = 1000</html>",
			section = weatherToggles,
			position = 19
	)
	@Range(max = 1000)
