	@ConfigItem(
			keyName = "partlyCloudyDensity",
			name = "Partly Cloudy Density",
			description = "<html>Sets the number of Cloud objects that spawn while Partly Cloudy<br>Max = 300</html>",
			section = weatherToggles,
			position = 20
