		return false;
	}

	@ConfigItem(
			keyName = "ashfallDensity",
			name = "Ashfall Density",
			description = "<html>Sets the number of Ash objects that spawn while in Ashfall<br>Max = 1200</html>",
			section = weatherToggles,
			position = 22
	)
	@Range(max = 1200)
	default int ashfallDensity()
