		return 200;
	}

	@ConfigItem(
			keyName = "enableFog",
			name = "Fog Enabled",
			description = "Allows Fog objects to appear while Foggy",
			section = weatherToggles,
			position = 23
	)
	default boolean enableFog()
	{
