	}

	@ConfigItem(
			keyName = "foggyDensity",
			name = "Fog Density",
			description = "<html>Sets the number of Fog objects that spawn while Foggy<br>Max = 1800</html>",
			section = weatherToggles,
			position = 24
	)
	@Range(max = 1800)
	default int foggyDensity()
