		return true;
	}

	@ConfigItem(
			keyName = "starryDensity",
			name = "Stars Density",
			description = "<html>Sets the number of Star objects that spawn while Starry<br>Max = 2000</html>",
			section = weatherToggles,
			position = 26
	)
